select pg_temp.ok(not has_function_privilege('authenticated','public.pw_reuse_section(uuid,uuid,integer,integer,uuid)','EXECUTE'),'reuse transaction is service-only');
select public.kb_metadata_save('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','dddddddd-dddd-4ddd-8ddd-dddddddddddd',0,'{"type":"certification","status":"approved","reviewedAt":"2026-10-25","expiresAt":null,"tags":["security"],"owner":null}');
select pg_temp.ok((select metadata->>'revision'='1' from public.kb_documents where id='dddddddd-dddd-4ddd-8ddd-dddddddddddd'),'metadata version saved');
do $$ begin
 begin perform public.kb_metadata_save('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','22222222-2222-4222-8222-222222222222','dddddddd-dddd-4ddd-8ddd-dddddddddddd',1,'{"type":"certification","status":"approved","reviewedAt":"2026-10-25","expiresAt":null,"tags":[],"owner":null}');raise exception 'FAIL editor approved';exception when insufficient_privilege then raise notice 'PASS editor cannot approve metadata';end;
 begin perform public.kb_metadata_save('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','33333333-3333-4333-8333-333333333333','dddddddd-dddd-4ddd-8ddd-dddddddddddd',1,'{"type":"other","status":"draft","reviewedAt":null,"expiresAt":null,"tags":[],"owner":null}');raise exception 'FAIL cross tenant';exception when no_data_found then raise notice 'PASS cross-tenant source hidden';end;
 begin perform public.kb_metadata_save('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','dddddddd-dddd-4ddd-8ddd-dddddddddddd',0,'{"type":"other","status":"draft","reviewedAt":null,"expiresAt":null,"tags":[],"owner":null}');raise exception 'FAIL stale metadata';exception when sqlstate 'PT409' then raise notice 'PASS stale metadata rejected';end;
end $$;
