insert into public.kb_answer_citations values('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','cccccccc-cccc-4ccc-8ccc-cccccccccccc','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
create temp table project(id uuid);
insert into project select public.pw_create('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','Fictional','{"schema":1,"title":"Fictional","requirements":[],"sections":[{"id":"ffffffff-ffff-4fff-8fff-ffffffffffff","title":"Support","text":"Fictional support capability","requirementIds":["r"],"status":"approved","unverified":false,"revision":0,"reviewedRevision":0}],"evidence":[{"id":"e","answerId":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","revision":0,"text":"Fictional support capability","requirementId":"r","decision":"accepted","stale":false,"citations":[{"id":"cccccccc-cccc-4ccc-8ccc-cccccccccccc"}]}]}');
