select pg_temp.ok((select count(*)=1 from public.kb_answers where approved_revision is null),'reused answer remains draft pending approval');
select public.kb_metadata_save('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','dddddddd-dddd-4ddd-8ddd-dddddddddddd',1,'{"type":"certification","status":"draft","reviewedAt":null,"expiresAt":null,"tags":[],"owner":null}');
select pg_temp.ok(jsonb_array_length(public.pw_candidates(id,'11111111-1111-4111-8111-111111111111','support'))=0,'draft metadata excluded from retrieval') from project;
select pg_temp.ok((select evidence_epoch=1 from public.pw_projects where id=(select id from project)),'metadata changes invalidate project evidence');
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select pg_temp.ok((select count(*)=0 from public.kb_documents),'existing source RLS hides metadata cross tenant');
reset role;
rollback;
